def metric_kilometers(meters: int) -> float:
    """Convert meters to kilometers, retaining fractional kilometers."""
    return meters // 1000

def fahrenheit(celsius: float) -> float:
    """Convert Celsius to Fahrenheit."""
    return celsius * 9 / 5

